  "{n} of the {total} logged orders are not linked to their sale on the till yet, so what they cost is not known. Import from Square brings the sales; an order can also be linked by hand.": "登记的 {total} 个订单中有 {n} 个还没有关联到收银系统中的销售，因此金额未知。从 Square 导入会带来销售记录；也可以手动关联。",
