  "{n} people have taken more leave than their {year} balance. Settle each under Owed days.": "{n} 人的休假超出了 {year} 年余额。请在“所欠天数”中逐一结清。",
  "{n} people have the day they were added to the OS as their hire date. If that is not when they started, set the real dates from a list.": "有 {n} 人的入职日期是他们被加入系统的那一天。如果那不是他们真正入职的日期，请从名单设置真实日期。",
  "{n} people have their own figure for at least one leave type instead of the company default.": "有 {n} 人至少有一类假期使用个人设定，而不是公司默认值。",
