  "{name} has no SSNIT number or TIN on their record, needed for filing SSNIT and PAYE.": "{name} 的档案中没有 SSNIT 号码或 TIN，申报 SSNIT 和 PAYE 需要这些信息。",
  "{name} has no VIP or IOU account yet, so those stay greyed out.": "{name} 还没有 VIP 或赊账账户，所以这两项保持灰色。",
