  "3 days before the due date, on the day, then 7 and 30 days late — once each, with the bill attached. Only bills that fell due in the last 45 days.": "到期前 3 天、到期当天、逾期 7 天和 30 天——各一次，并附上账单。仅限最近 45 天内到期的账单。",
  "3 days before the due date, on the day, then 7 and 30 days late — once each. Only bills that fell due in the last 45 days; older debts are for a person to chase.": "到期前 3 天、到期当天，以及逾期 7 天和 30 天时——各发一次。仅限过去 45 天内到期的账单；更早的欠款由人工催收。",
