  "a weekday": "工作日",
  "A WhatsApp or text message asking the client to pay, sent from here or the Payment reminders page.": "请客户付款的 WhatsApp 或短信，可从此处或付款提醒页面发送。",
  "A won deal stays with the prospects until it is paid.": "已成交的交易在付款前仍留在潜在客户中。",
