  "An offer is costed as a draft, sent to the prospect, and once accepted becomes a booking. Press a step to show only those.": "报价先作为草稿核价，再发给意向客户，接受后即成为预订。点按某一步只显示这些报价。",
  "An optional record of the total days agreed with a person, checked against how it is split across the types. It does not limit any request.": "可选，记录与某人约定的总天数，并与各类假期的分配核对。不会限制任何申请。",
