  "Annual, compassionate and sick leave all come out of this total. The year's company holidays are part of it, so they are taken off on 1 January; a holiday added or removed during the year changes it at once. Taking more than is left is allowed: the extra days are owed to the company, and HR settles them.": "年假、事假和病假都从这个总额中扣除。当年的公司假日包含在内，于 1 月 1 日扣除；年中增减假日会立即改变余额。可以超出剩余天数休假：多出的天数欠公司，由人事处理结清。",
  "Annual, compassionate and sick leave all come out of this total. The year's company holidays are taken off on 1 January, and the balance follows the holiday list as it changes. More than is left can be taken: the extra days are owed and settled by HR.": "年假、事假和病假都从这个总额中扣除。当年的公司假日于 1 月 1 日扣除，余额随假日列表的变化而变化。可以超出剩余天数休假：多出的天数为欠款，由人事结清。",
