  "attendance.recorded: a clock-in, a clock-out or a change by HR; it always carries the whole record as it is now, so save it over what you have with the same attendance id. attendance.removed: HR deleted the record; delete yours. feed.test: sent by the Send a test button; just answer 2xx. status is present, late, absent or half_day; shift is 1 or 2 (a second shift the same day); clockOut is empty while they are still at work; autoClockedOut means nobody clocked out and the OS closed the shift at its limit.": "attendance.recorded：上班打卡、下班打卡或人事部的修改；它总是包含当前的完整记录，请用它覆盖相同考勤 id 的记录。attendance.removed：人事部删除了该记录；请删除您的记录。feed.test：由“发送测试”按钮发送；只需返回 2xx。status 为 present、late、absent 或 half_day；shift 为 1 或 2（同一天的第二个班次）；仍在上班时 clockOut 为空；autoClockedOut 表示无人打卡下班，系统在时限到达时自动结束了该班次。",
