  "By law PAYE is worked out on every payslip and paid to GRA. Each company decides who bears it: its staff, taken off their pay, or the company itself as a cost, so take-home pay keeps it. A change updates draft runs at once; approved and paid runs stay as they were paid.": "按法律规定，每张工资单都要计算 PAYE 并缴纳给 GRA。每个公司决定由谁承担：由员工从工资中扣除，或由公司作为成本承担，这样实发工资不受影响。更改会立即更新草稿工资单；已批准和已发放的工资单保持原样。",
