  "Calls, replies, notes, stage moves, quotations and wins logged in the OS, as on the sales board. The daily goal is the same too.": "在 OS 中记录的电话、回复、备注、阶段变更、报价和成交，与销售看板相同。每日目标也相同。",
  "Calls, visits and texts from a personal phone: write them down on the customer's profile (\"Log a call or visit\").": "用个人手机进行的通话、拜访和短信：记录在客户档案上（“记录通话或拜访”）。",
  "CAM / service charge": "CAM / 服务费",
  "CAM runs from the 25th of one month to the 25th of the next, invoiced on the 25th. The first invoice covers from this day to the next 25th, by the day. Leave empty to start today (or when the booking starts).": "公共区域维护费（CAM）从每月 25 日计至下月 25 日，于 25 日开票。第一张发票从这一天算到下一个 25 日，按天计费。留空则从今天（或租约开始之日）开始。",
  "CAM, water & power and other rent-side invoices found in Bamboo Products' invoices. Untick anything that is not rent-side, say what each customer's charges are, then move them to Poki. Payments and receipts move with them.": "在 Bamboo Products 的发票中找到的 CAM、水电费及其他租赁类发票。取消勾选不属于租赁的发票，注明每位客户的费用类型，然后转到 Poki。付款和收据会一并转移。",
