  "Connect {restaurant}'s Facebook Page (and the Instagram account linked to it) on the Social tracker; its messages then come in here.": "在社交追踪中连接 {restaurant} 的 Facebook 主页（及其关联的 Instagram 账号），之后消息就会进入这里。",
  "Connect {restaurant}'s own number. It can stay in the WhatsApp Business app on the restaurant phone: staff keep using it there, and the OS gets every message.": "连接 {restaurant} 自己的号码。号码可以继续保留在餐厅手机的 WhatsApp Business 应用中：员工照常使用，系统也会收到每条消息。",
  "Connect a channel": "连接一个渠道",
  "Connect a mailbox": "连接邮箱",
  "Connect a new number instead": "改为连接新号码",
  "Connect on the Social tracker": "在社交追踪中连接",
  "Connect one": "连接一个",
  "Connect printer": "连接打印机",
  "Connect the company WhatsApp number so customers' messages land in the CRM inbox. The number can stay in the WhatsApp Business app on the company phone: staff keep using it there, and the OS gets every message, the replies typed on the phone, the saved contacts and up to about 6 months of past chats.": "连接公司的 WhatsApp 号码，让客户消息进入 CRM 收件箱。该号码可以继续保留在公司手机的 WhatsApp Business 应用中：员工照常使用，系统会收到每条消息、在手机上输入的回复、已保存的联系人，以及最多约 6 个月的历史聊天。",
  "Connect the number": "连接号码",
  "Connect the printer: pair it in System Settings → Bluetooth, or plug in its USB cable.": "连接打印机：在“系统设置 → 蓝牙”中配对，或插上其 USB 线。",
  "Connect the sales mailbox, so customers' emails land in the CRM inbox on their profiles, and replies written there go out from that mailbox.": "连接销售邮箱：客户的邮件会进入 CRM 收件箱并归到其档案上，在那里写的回复会从该邮箱发出。",
  "Connect the WhatsApp Business app": "连接 WhatsApp Business 应用",
