  "Copy the name (or employee ID) and start date columns from your HR or payroll sheet and paste them below, one person per line. Dates like 11/03/2019, 2019-03-11 or 11 Mar 2019 all work. You will see who each line matches and what changes before anything is saved.": "从人事或工资表中复制姓名（或工号）和入职日期两列，粘贴到下方，每行一人。11/03/2019、2019-03-11 或 11 Mar 2019 这样的日期都可以。保存之前，您会看到每行对应的是谁以及会改动什么。",
