  "For a customer, with what to bring.": "为客户安排，并注明要带的东西。",
  "For a page with no server of its own, like publicfigah.com/#board: its pages may then read this feed with the read key. Anyone who looks at that page's code can see the key and read the same names and clock times, so only for a page shared with people who may see them.": "适用于没有自己服务器的网页，例如 publicfigah.com/#board：该网站的网页可以用读取密钥读取此数据源。任何查看该网页代码的人都能看到密钥，并读取同样的姓名和打卡时间，因此仅适用于只分享给有权查看者的网页。",
  "For a record entered by mistake: the bamboo goes back to its batch and the output comes off stock.": "用于误录的记录：竹子退回原批次，产出从库存中扣除。",
  "For Alipay and WeChat Pay": "支付宝和微信支付",
  "for an answer": "等待答复",
  "For birthday wishes and news from the restaurant. Each message has a link to stop them.": "用于生日祝福和餐厅消息。每条消息都附有退订链接。",
  "For bookings measured in days. Left blank, a day is charged at a thirtieth of the monthly rate.": "适用于按天计算的租约。留空时，每天按月租的三十分之一计费。",
  "For cash": "现金",
  "For drinks and things counted one by one. Each sale takes it off; when new stock comes in, enter it under Stock. The till shows what is left and stops at none.": "适用于饮料和按件计数的东西。每次销售自动扣减；新货到时，在“库存”中录入。收银台显示剩余数量，卖完即停。",
  "For every company.": "适用于所有公司。",
  "For filing SSNIT and PAYE. For most people the TIN is now their Ghana Card number. Only people who manage payroll can see these.": "用于申报 SSNIT 和 PAYE。对大多数人来说，TIN 现在就是他们的 Ghana Card 号码。只有管理工资的人才能看到这些信息。",
  "For goods leaving the site: a manager approves it, security lets it out.": "用于带出厂区的物品：经理批准，保安放行。",
  "For how many months": "共计多少个月",
  "For items made to order: how many days they take, e.g. 3 to 7. Customers see it on the item and at checkout, with the days their order will be ready between. Leave empty for items in stock.": "适用于定制商品：需要几天制作，例如 3 到 7 天。客户会在商品页和结账时看到，并显示订单的预计完成日期。有现货的商品留空。",
