  "Guests appear here from three places: the order sheet customer service has kept (import it once), new phone, WhatsApp and Bolt orders logged here, and sales rung up on Square with a customer.": "客人来自三个地方：客服之前的订单表（导入一次即可）、在这里登记的新电话/WhatsApp/Bolt 订单，以及在 Square 上带客户信息的销售。",
