  "Hello": "您好",
  "Hello {{1}}, your order {{2}} is ready for pickup at Bamboo Products.": "{{1}} 您好，您的订单 {{2}} 已可在 Bamboo Products 取货。",
  "Hello {name}": "{name} 你好",
  "Hello {name} 👋": "{name} 您好 👋",
  "Hello {name}, about the products you sent:": "{name} 您好，关于您发来的产品：",
  "Hello {name}, here is your contract with Bamboo Products, {title} ({no}), to read and sign: {url}": "{name} 您好，这是您与 Bamboo Products 的合同《{title}》（{no}），请阅读并签署：{url}",
  "Hello {name}, I am bringing your order from {place}.": "{name} 您好，我正在给您送 {place} 的订单。",
  "Hello {name}, it is fixed": "{name}，您好，已经修好了",
  "Hello {name}, this is {rep} from Bamboo Products. You asked us about bamboo products before, so we wanted you to be among the first to know: {what} is now available. Would you like the prices and photos? Reply here and we will send them.": "{name} 您好，我是 Bamboo Products 的 {rep}。您之前咨询过我们的竹制品，所以我们想让您第一时间知道：{what} 现已上市。需要价格和照片吗？在这里回复，我们会发给您。",
  "Hello {name}, this is about your order {ref}.": "{name} 您好，这是关于您的订单 {ref}。",
  "Hello {name}, this request is closed": "{name}，您好，此申请已关闭",
  "Hello {name}, we are coming to fix it": "{name}，您好，我们将上门维修",
  "Hello {name}, we have your request": "{name}，您好，我们已收到您的申请",
  "Hello {name}, your order is waiting for your payment": "{name}，您好，您的订单正在等待付款",
  "Hello {name}, your order is: {state}": "{name}，您好，您的订单状态：{state}",
  "Hello {name}!": "{name}，您好！",
  "Hello, {name}": "您好，{name}",
  "Hello, thank you for telling us about your visit. We are sorry it was not right. We would love to make it up to you.": "您好，感谢您告诉我们这次用餐的情况。很抱歉没能让您满意，我们希望能弥补。",
  "Hello!": "您好！",
  "Hello! Thank you for writing to Bamboo Products. How can we help you?": "您好！感谢您联系 Bamboo Products。请问有什么可以帮您？",
  "Hello! You can pay \"{title}\" to Bamboo Products here, by card or Mobile Money: {url}": "您好！您可以在这里向 Bamboo Products 支付“{title}”，可用银行卡或移动钱包：{url}",
  "Help": "帮助",
  "Help with an event": "活动协助",
  "Helped on": "协助",
  "helped on {n}": "协助了 {n} 个",
  "Here are the {n} products {rep} picked for you.": "这是 {rep} 为您挑选的 {n} 件产品。",
  "Here is how {scope} is doing today: who is in, what is waiting for you, and what needs attention.": "以下是{scope}今天的情况：谁到岗了、什么在等您处理、什么需要关注。",
  "Here is the menu and the price. Pay the deposit to book the day.": "这是菜单和价格。支付订金即可预订当天。",
