  "Hi {firstName}, this sets up face recognition for the clock-in kiosk — once done, you'll need to look at the kiosk's camera (in addition to your PIN) every time you clock in or out.": "{firstName} 您好，这将为打卡机设置人脸识别 — 完成后，您每次上下班打卡时都需要看向打卡机摄像头（同时输入 PIN）。",
