  "If {email} has an account, we've emailed a code to it. It works for {n} minutes.": "如果 {email} 有账户，我们已将验证码发送到该邮箱。有效期 {n} 分钟。",
  "If {email} has an account, we've texted a code to the phone on it. It works for {n} minutes.": "如果 {email} 有账户，我们已将验证码短信发送到其绑定的手机。有效期 {n} 分钟。",
  "If {to} is the one you gave us, a code is on its way. It works for {n} minutes.": "如果 {to} 是您留给我们的，验证码已在路上，{n} 分钟内有效。",
  "If found, please hand it in at the gate.": "如拾获，请交到大门处。",
  "If found, please return it to:": "如拾到，请交还至：",
  "If it has one: the hours come from it.": "如有：小时数以此为准。",
  "If it is approved you will owe the company {n} day(s). You can still send it; HR settles owed days.": "如获批准，您将欠公司 {n} 天。您仍可提交；欠假由人事部处理。",
  "If nobody has closed it by then. A time before noon closes the night before, for late nights. A day with no sale and no drawer is not closed.": "如果到时还没有人结账。设在中午之前的时间会结算前一天，适合营业到深夜的情况。没有销售也没有开过钱箱的日子不会结账。",
  "If people remember one sentence, which is it? Every post, flyer and talk should say it.": "如果人们只记住一句话，会是哪一句？每个帖子、传单和讲话都应传达它。",
  "If the company gives you a float to spend for it, ask finance to open an expense sheet for you. You will then record here what you spend and the money you receive.": "如果公司给您备用金替公司花钱，请让财务为您开设费用表。之后您在这里记录支出和收到的钱。",
  "If the unit's fixed utility fee was already included in the booking price, don't add it again here.": "如果该单元的固定水电费已包含在预订价格中，请勿在此重复添加。",
  "If there is one": "如有",
  "If you left at a different time, tell your supervisor so they can correct it. Remember to clock out at the end of every shift.": "如果您实际离开的时间不同，请告诉您的主管以便更正。请记得在每个班次结束时打下班卡。",
  "If you lose your phone, each of these signs you in once instead of the code from the app. Keep them somewhere safe — they won't be shown again.": "如果手机丢失，每个备用码可代替应用中的验证码登录一次。请妥善保存——它们不会再显示。",
