  "Invoices issued in the period (voided ones left out) plus restaurant till sales.": "该期间开具的发票（不含作废）加餐厅收银销售。",
  "Invoices issued in the period, voided ones left out, added up in each currency.": "该期间开具的发票，不含作废发票，按币种合计。",
  "Invoices not fully paid, in each currency. Overdue means past the due date. Voided invoices don't count.": "未全额付清的发票，按币种列出。逾期指已过到期日。作废发票不计入。",
  "Invoices not yet paid. Overdue means past the due date.": "尚未支付的发票。逾期表示已过到期日。",
