  "Invoices raised again by themselves. Open an invoice and press Repeat to add one.": "自动重复开具的发票。打开一张发票并点击“重复”即可添加。",
  "Invoices show both ways to pay, and quotations carry terms & conditions.": "发票上有两种付款方式，报价也附有条款与条件。",
  "Invoices show no bank account, so clients can't pay by transfer from the invoice alone.": "发票上没有银行账户，客户无法仅凭发票转账付款。",
  "Invoices show no mobile money number.": "发票上没有移动支付号码。",
  "Invoices take their quantity off this by themselves when they are made, and put it back if voided. Use this for deliveries, returns and stocktake corrections.": "发票开具时会自动从这里扣除数量，作废时会退回。此处用于到货、退货和盘点更正。",
