  "Invoices, quotations and estimates go only when someone presses Email on the document, after reading the message. These two go on their own; at most {n} automatic reminder emails a day.": "发票、报价和估价只有在有人阅读消息后在文件上点击「电子邮件」时才会发送。以下两项会自动发送；每天最多 {n} 封自动提醒邮件。",
  "Invoices, quotations, receipts and payment reminders to customers, and sign-in codes to staff, sent from one of the company's own mailboxes.": "从公司自己的邮箱向客户发送发票、报价、收据和付款提醒，并向员工发送登录验证码。",
