  "It can take up to a minute when it has been quiet. You stay signed in.": "服务器闲置后可能需要一分钟才能响应。您仍保持登录。",
  "It can wait a little": "可以稍等处理",
  "It comes off this restaurant's stock now, at what it cost; they count it in when it arrives.": "现在按成本从本店库存扣除；对方到货时清点入库。",
