  "It goes straight to the kitchen. You pay at the end, as usual.": "订单会直接送往厨房。像往常一样最后结账。",
  "It goes to the manager, who sees it under Disputes and says how it was resolved.": "它会发送给经理，经理在“纠纷”中查看并说明解决方式。",
  "It goes to the till and the kitchen by itself when it is time to cook.": "到了该做的时候，会自动进入收银台和厨房。",
  "It happened. Write what was found so whoever quotes has the measurements.": "已进行。请写下发现，方便报价人员获取尺寸。",
  "It has a sale linked, so it is a real lead.": "它已关联一笔销售，所以是真正的线索。",
  "It has arrived. The requester is told at each step.": "已到货。每一步都会通知申请人。",
