  "It is removed for everyone in the chat, with its files. A note that it was deleted stays in its place.": "它会连同文件一起对聊天中的所有人删除。原位置会保留一条已删除的提示。",
  "It is still cooking: we bring it out as soon as it is ready.": "还在制作中：一做好就给您送出来。",
  "It is taken off the approval list. You can ask again later.": "它将从审批列表中移除。您以后可以重新申请。",
