  "It lacks {scopes}: connect the number again and allow WhatsApp.": "缺少 {scopes}：请重新连接号码并允许 WhatsApp。",
  "It lacks {scopes}. Add them to the Facebook Login for Business configuration set on Render (META_PAGES_CONFIG_ID), then connect with Facebook again.": "缺少 {scopes}。请将其添加到 Render 上设置的 Facebook Login for Business 配置（META_PAGES_CONFIG_ID）中，然后重新用 Facebook 连接。",
  "It lacks {scopes}. Connect with Facebook again and leave every permission ticked in Meta’s window.": "缺少 {scopes}。请重新用 Facebook 连接，并在 Meta 的窗口中保留所有权限的勾选。",
  "It leaves the register and its reminders stop.": "它将移出登记簿，提醒也会停止。",
