  "It no longer works — usually because the Facebook password was changed or the person who connected is no longer an admin of the Page. Connect with Facebook again.": "令牌已失效——通常是因为 Facebook 密码已更改，或连接的人已不再是主页管理员。请重新用 Facebook 连接。",
  "It no longer works: connect the number again.": "它已失效：请重新连接号码。",
  "It reaches them in My space; their reply comes back here.": "质询会发到其“我的空间”，答复会回到这里。",
  "It runs out {when}: connect the number again before then.": "它将于{when}过期：请在此之前重新连接号码。",
  "It searches the OS before answering. If it can't find something, or your role can't see it, it says so rather than guessing.": "它会先在 OS 中搜索再回答。如果找不到，或您的角色无权查看，它会直接说明而不是猜测。",
