  "Keep the signing secret on your server only. The read key too, unless your web page reads the feed itself: then anyone who looks at the page's code can see it and read the same names and clock times, so share the page only with people who may see them. If either is ever seen by someone it shouldn't be, ask for a new one: the old one stops working at once.": "签名密钥只保存在您的服务器上。读取密钥也是如此，除非您的网页自己读取数据源：此时任何查看网页代码的人都能看到它，并读取同样的姓名和打卡时间，所以只把该网页分享给有权查看的人。如果有不该看到的人看到了任一密钥，请索取新的：旧的会立即失效。",
