  "Message copied. Put each customer's name in place of {name}.": "消息已复制。请将 {name} 替换为每位客户的名字。",
  "Message deleted.": "消息已删除。",
  "Message only people who wrote to you or agreed to hear from you, and send fewer messages they didn't ask for. The limit goes back up when the quality improves.": "只给主动联系过你或同意接收消息的人发消息，并减少对方未要求的消息。质量改善后，上限会恢复。",
  "Message template “{name}” ({lang}) was approved.": "消息模板“{name}”（{lang}）已获批准。",
