  "Message templates": "消息模板",
  "Message to {name} on WhatsApp": "通过 WhatsApp 发给 {name} 的消息",
  "Message to customer": "给客户的留言",
  "message waiting for a reply": "条消息等待回复",
  "Message… (@ to mention)": "消息…（@ 提及）",
