  "mNotify didn't say. Try the check again in a minute.": "mNotify 没有答复。请一分钟后再检查。",
  "mNotify doesn't know this sender ID, so every text fails. Ask mNotify to approve it, or switch to one already approved.": "mNotify 不认识这个发件人 ID，所以每条短信都会失败。请让 mNotify 审批它，或改用已获批准的 ID。",
  "mNotify reads this before approving the name. Approval usually takes up to a working day; the screen shows when it comes through.": "mNotify 会在审批名称前阅读这段说明。审批通常最多需要一个工作日；批准后此页面会显示。",
  "mNotify refused to send from it: it isn't approved on the account yet. Check it, ask mNotify to approve it, or switch to one already approved.": "mNotify 拒绝用它发送：它在账户上尚未获批。请检查它、让 mNotify 审批，或改用已获批准的 ID。",
