  "Money received": "收到的钱",
  "Money received minus money spent. Above zero it is cash the officer holds; below zero the company owes the officer.": "收到的钱减去支出。大于零是经办人手中的现金；小于零则是公司欠经办人的钱。",
  "Money someone spent for the business and asks to have paid back, with a photo of the receipt.": "某人为公司垫付并申请报销的费用，附收据照片。",
  "Money spent": "支出",
  "Money spent from your drawer: what for, who to, and a photo of the receipt.": "从钱箱支出的钱：用途、付给谁，以及收据照片。",
  "Money that actually moved in the period: payments and till sales in; expense claims paid out, pay runs marked paid and purchases received out. What is approved but not paid is shown separately.": "该期间实际发生的资金流动：流入为付款和收银销售；流出为已支付报销、已标记支付的发薪和已收货采购。已批准但未支付的单独列出。",
  "Money that came in long ago is dated when it was due, so it does not count as money in this week.": "很久以前收到的款项记在到期日，因此不会计入本周收款。",
  "Money the company gives an officer to spend for it. The usual float is the amount they are topped up to.": "公司交给经办人替公司开支的钱。常规备用金是每次补足到的金额。",
  "Money the officer asks finance for. Once approved it is added to the sheet as money received.": "经办人向财务申请的钱。批准后作为收到的钱记入费用表。",
  "Money with riders: {amount}": "骑手手上的钱：{amount}",
