  "Off: a waiter or the cashier accepts each order on the till first (the till rings). On: it goes to the kitchen at once, onto the table's open order.": "关闭：服务员或收银员先在收银机上接受每笔订单（收银机会响铃）。开启：订单立即送往厨房，并加入本桌的未结订单。",
  "Off: hidden from the till for now (sold out for the day, out of season), kept on the menu.": "关闭：暂时不在收银台显示（当天售完、过季），仍保留在菜单上。",
