  "Orders completed on the till. A voided order is not counted.": "收银台完成的订单。作废订单不计入。",
  "Orders customer service takes by phone, WhatsApp or Bolt, newest first, with what the guest said. Each is linked to its sale on the till when the OS finds it.": "客服通过电话、WhatsApp 或 Bolt 接的订单，最新的在前，附客人反馈。系统找到对应销售时会自动关联到收银记录。",
