  "Orders for later still come in": "预约订单仍可下单",
  "Orders from Bolt Food, Glovo and others are rung up on the till as the app's (More → Delivery-app order): at the app's prices, paid on the app, and kept apart in the reports.": "Bolt Food、Glovo 等平台的订单在收银台按平台订单录入（更多 → 外卖平台订单）：按平台价格、在平台付款，并在报表中单独列出。",
  "Orders from the QR codes go straight to the kitchen; tables with no waiter yet wait here.": "扫码订单直接送往厨房；还没有服务员的餐桌在这里等待。",
  "Orders from the QR codes wait here to be accepted.": "扫码订单在这里等待接受。",
  "Orders from the shop on the website, paid before they show here; checkouts not paid wait under \"Not paid yet\" and are cancelled after two days. Move them along: the customer is told at each step.": "网站商店的订单，付款后才会显示在这里；未付款的结账放在“尚未付款”下，两天后自动取消。逐步推进订单，每一步都会通知顾客。",
