  "Press a campaign for its whole story. The bar under the name is how far through its dates it is.": "点击营销活动可查看完整情况。名称下方的进度条表示其日期进度。",
  "Press a claim to see its receipt, decide it or pay it out.": "点击申请查看收据、审批或报销。",
  "Press a client for everything done with them.": "点击客户查看与其往来的全部记录。",
  "Press a colour to copy its code. “Aa” shows the text colour that reads on it.": "点击颜色即可复制色号。“Aa”显示在其上清晰可读的文字颜色。",
  "Press a coupon to log its uses or change it.": "点击优惠券可记录使用或修改。",
