  "Press a role to see who holds it and change what it may do.": "点击角色可查看谁担任并更改其权限。",
  "Press a run to see every payslip, change days worked while it is a draft, approve it and mark it paid.": "点击发薪查看每张工资单，在草稿阶段修改出勤天数，批准并标记为已支付。",
  "Press a sheet to open it. The ring is the balance against the usual float; red means the company owes them.": "点击费用表即可打开。圆环表示余额占常规备用金的比例；红色表示公司欠对方钱。",
