  "Pull follower counts and recent VODs into the social tracker (requires a Twitch developer application).": "将粉丝数和最近的点播视频拉取到社交追踪中（需要 Twitch 开发者应用）。",
  "Pull page post reach, engagement and follower counts into the social tracker (requires a Meta developer app + Page access token).": "将主页帖子覆盖、互动和粉丝数拉取到社交追踪中（需要 Meta 开发者应用 + 主页访问令牌）。",
  "Pull post/reel engagement and follower counts into the social tracker (requires a Meta developer app + Instagram professional account link).": "将帖子／Reels 互动和粉丝数拉取到社交追踪中（需要 Meta 开发者应用 + 关联 Instagram 专业账户）。",
  "Pull video views and engagement into the social tracker (requires a Google Cloud project with the YouTube Data API enabled).": "将视频播放量和互动拉取到社交追踪中（需要启用了 YouTube Data API 的 Google Cloud 项目）。",
  "Pull video views and engagement into the social tracker (requires a TikTok for Business developer app).": "将视频播放量和互动拉取到社交追踪中（需要 TikTok for Business 开发者应用）。",
  "Pull website visits into the social tracker’s Website channel (requires a GA4 property + service account).": "将网站访问量拉取到社交追踪的“网站”渠道（需要 GA4 媒体资源 + 服务账号）。",
  "Pulls clock in/out shifts for every employee linked to TimeStation (set via \"Sync from TimeStation\" on the Employees page) over the date range below. TimeStation wins for anyone it covers — this replaces any existing attendance record for those dates, including manual corrections. Employees not linked to TimeStation are untouched.": "拉取下方日期范围内、所有已关联 TimeStation 的员工的上下班打卡记录（关联方式：在“员工”页面使用“从 TimeStation 同步”）。对于 TimeStation 覆盖的人员，以 TimeStation 为准 — 这将覆盖这些日期上已有的考勤记录，包括手动更正。未关联 TimeStation 的员工不受影响。",
  "Pulls your live employee list from TimeStation (name, title, group, email, hourly rate, kiosk PIN). Groups that don't already exist here are created automatically. Records with no email on TimeStation are shown with a blank field below — type one in to import that person, use \"Fill in all missing emails\" to import everyone at once with a placeholder address, or leave a field blank to skip just that person. Hourly rate is imported as-is (used by the Attendance report's pay column) — HR still sets the real daily rate for Payroll separately. TimeStation's PIN is imported as the kiosk PIN automatically; if it clashes with one already in use here, that employee is still created with the PIN left unset for HR to assign manually. Live clock in/out status isn't imported — it's a snapshot, not an employment status.": "从 TimeStation 拉取您当前的员工名单（姓名、职位、分组、邮箱、时薪、考勤机 PIN 码）。此处尚不存在的分组会自动创建。在 TimeStation 上没有邮箱的记录，下方会显示为空白字段 — 填入邮箱即可导入该人员，使用“填充所有缺失邮箱”可用占位地址一次性导入全部人员，或将某字段留空以跳过该人员。时薪按原值导入（用于考勤报表的薪酬列）— 人事部门仍需另行设置用于薪资核算的实际日薪。TimeStation 的 PIN 码会自动导入为考勤机 PIN 码；若与此处已使用的码冲突，该员工仍会被创建，但 PIN 码留空，由人事手动分配。实时打卡状态不会导入 — 那只是一个瞬时快照，并非在职状态。",
