  "Sales are what these leads' customers were invoiced from the day the lead came in until 90 days after the campaign ends, plus promotion and event sales.": "销售额是这些潜在客户对应的客户从线索进入当天到活动结束后 90 天内的开票金额，加上促销和活动销售额。",
