  "Social security on each person's salary for SSNIT (their basic salary unless another figure is set on their record), whatever days they worked: 5.5% taken from staff pay and 13% the employer adds on top, both paid to SSNIT. A run shorter than a month charges its share; nothing earned, none. A daily-rate person with no salary for SSNIT pays on what they earned.": "社会保障按每人的 SSNIT 缴费工资计算（除非其档案中另有金额，否则为基本工资），与出勤天数无关：从员工工资中扣除 5.5%，雇主另加 13%，均缴给 SSNIT。不足一个月的发薪按比例计算；没有收入则不计。没有 SSNIT 缴费工资的日薪员工按实际收入缴纳。",
