  "That receipt is too big (6 MB at most).": "收据太大（最多 6 MB）。",
  "That sale was voided: there is nothing to refund.": "该销售已作废，无需退款。",
  "The {category} claim of {amount} has no receipt yet.": "{amount} 的{category}报销尚无收据。",
  "The {held} deposit they hold goes with them; {owing} more is charged for the new unit.": "他们已付的 {held} 押金随之转移；新单元另收 {owing}。",
  "The {held} deposit they hold goes with them.": "他们已付的 {held} 押金随之转移。",
  "The {n} days before": "之前 {n} 天",
  "The {n} extra days are priced at nothing: this booking was made before extra days were always charged. Press Edit, then Save, to charge them at {rate} a day.": "额外的 {n} 天未计费：此预订创建于额外天数始终计费之前。请点击编辑，然后保存，按每天 {rate} 计费。",
  "The {n} that don't say what they are": "未注明类型的 {n} 张",
  "The {n} with the nearest deadlines; {m} more further out.": "截止日期最近的 {n} 个；另有 {m} 个在更远的将来。",
