  "The assistant isn't switched on yet. An administrator needs to add the Anthropic API key (ANTHROPIC_API_KEY) to the backend's environment on Render. Until then every question gets this same answer.": "助手尚未开启。管理员需要在 Render 上将 Anthropic API 密钥（ANTHROPIC_API_KEY）添加到后端环境中。在此之前，每个问题都会得到同样的答复。",
  "The attendance feed \"{name}\" can't reach {host}: {why} Clock-ins wait and are sent when it answers.": "考勤数据源“{name}”无法连接 {host}：{why} 打卡记录会等待，对方响应后再发送。",
  "The average gap of every price logged for each competitor. The middle line is our price; left of it they are cheaper, right of it dearer.": "每个竞争对手所有已记录价格的平均差距。中线是我们的价格；左侧表示他们更便宜，右侧表示更贵。",
