  "The booking on {unit} ends on the moving day; a new one carries on in the new unit until {date}. Their rent stays on their booking's invoice, so only the difference is settled.": "{unit} 的预订在搬家当天结束；新单元的新预订延续到 {date}。租金仍在原预订的发票上，因此只结算差额。",
