  "The camera was not allowed. Allow it in the browser, or type the code.": "未允许使用摄像头。请在浏览器中允许，或输入条码。",
  "The cash drawer: in the printer's driver settings (Printers & Scanners → Options), set the cash drawer to open with each receipt.": "钱箱：在打印机驱动设置（打印机与扫描仪 → 选项）中，将钱箱设为每张收据打印时打开。",
  "The cash is {amount} short of the sheet.": "现金比费用表少 {amount}。",
  "The cashier can switch any order to dine in, to go, pickup or delivery.": "收银员可以把任何订单切换为堂食、外带、自取或外送。",
  "The cashier counts it in on the till when the rider hands it over.": "骑手交钱时，收银员在收银机上点收。",
