  "The channel is signed in to the company's own account; Sync now fetches the latest posts and follower count.": "该渠道已登录公司自己的账户；“立即同步”会获取最新帖子和粉丝数。",
  "The channel the customer writes on, else their phone (WhatsApp), else their email.": "客户联系我们的渠道；否则为其电话（WhatsApp）；再否则为其邮箱。",
  "The checklist": "检验清单",
  "The choices, with commas: Monday, Friday": "选项，用逗号分隔：周一, 周五",
  "The clearer the brief, the sooner it comes back right. Marketing is told straight away.": "需求越清楚，越快得到满意的结果。市场部会立即收到通知。",
  "The client has the goods. The next step is the invoice, if one wasn't made earlier.": "客户已收到货物。下一步是开票（如之前未开）。",
  "The client said yes. The next step is the invoice.": "客户已同意。下一步是开票。",
  "The clock shows {h} h past the shift": "打卡显示比班次多 {h} 小时",
  "The clock shows less than the hours asked for.": "打卡记录少于申请的小时数。",
  "The closing figure on each day. A marked figure is a count that differed from the expected closing; hover it to see both.": "每天的结存数。标记的数字表示清点数与预计结存不同；悬停可查看两者。",
  "The code changes every 30 minutes.": "代码每 30 分钟更换一次。",
  "The code for what was done, like leave.decide or invoice.void: the area, then what happened.": "所做操作的代码，例如 leave.decide 或 invoice.void：先是领域，再是具体操作。",
  "The code on the board": "屏幕上的代码",
  "The code on the kiosk": "点餐机上的代码",
  "The code on the screen": "屏幕上的代码",
  "The codes to put on the tables": "放在餐桌上的二维码",
  "The columns were not found by their names: choose them below.": "未能按名称识别列：请在下方选择。",
  "The companies and people Bamboo Products quotes and invoices: where each one stands, what they owe and how to reach them. Press a number to show only those.": "Bamboo Products 为其报价和开票的公司和个人：各自的进展、欠款以及联系方式。点击数字只显示这些。",
  "The companies in the group and their departments.": "集团内的公司及其部门。",
  "the company": "公司",
  "The company": "公司",
  "The company owes {n} officers {amount} spent from their own pocket.": "公司欠 {n} 位经办人共 {amount}，是他们自掏腰包垫付的。",
  "The company owes {n} officers {amount} they spent from their own pocket.": "公司欠 {n} 位经办人共 {amount}，是他们自掏腰包垫付的。",
  "The company owes {name} {amount} for what they paid themselves.": "{name} 自己垫付的钱，公司欠其 {amount}。",
  "The company owes {name} {amount} they spent from their own pocket.": "公司欠 {name} {amount}，是其自掏腰包垫付的。",
  "The company owes {name} {amount}: what they spent beyond what they were given. Record what you pay them; it goes on their sheet as money received.": "公司欠 {name} {amount}：即其超出所领款项的支出。记录您付给对方的钱；它会作为收到的钱记入其费用表。",
  "The company owes 1 officer {amount} spent from their own pocket.": "公司欠 1 位经办人 {amount}，是其自掏腰包垫付的。",
  "The company owes you {amount} for what you paid yourself.": "您自己垫付的钱，公司欠您 {amount}。",
  "The company owes you {amount} on your expense sheet. Finance pays it back.": "您的费用表显示公司欠您 {amount}。财务会还给您。",
  "The company owes you {amount}. Finance gets your request and records it on your sheet when they pay you.": "公司欠您 {amount}。财务收到申请后，在付款时记入您的费用表。",
  "The company pays its staff's PAYE. Take-home = gross − SSNIT.": "公司承担员工的 PAYE。实发 = 总额 − SSNIT。",
  "The company profile is missing a short name or country.": "公司资料缺少简称或国家。",
  "The company-wide choices everything else follows: names, working time, currencies, text messages and email. Every change is written to the audit log.": "全公司通用、其他一切都遵循的设置：名称、工作时间、货币、短信和邮件。每次更改都会写入审计日志。",
  "The company-wide days a year for each type. A person can have their own figure instead (Adjust, below).": "每类假期的公司统一年天数。个人可以有自己的设定（见下方“调整”）。",
  "The company-wide default for this type. A person can have their own figure instead: press Adjust next to them under Balances.": "此类假期的公司默认值。个人可以有自己的设定：在“余额”中点击其旁边的“调整”。",
  "The company, site or job the money was spent for.": "这笔钱用于哪个公司、工地或项目。",
  "The company’s Facebook Page": "公司的 Facebook 主页",
  "The company's public holidays (set in Leave types & balances) on someone's working days are days paid, for daily-rate and salaried staff alike. A holiday they worked is paid once. Not for someone with no other day paid in the period, or before they were hired.": "公司的公共假日（在“假期类型与余额”中设置）若落在员工的工作日，即为带薪天数，日薪和月薪员工均适用。假日当天上班只计一次。该期间没有其他带薪天数的人不计，入职前的假日也不计。",
  "The Connect button for {names} can't work until the platform's app keys are on the server.": "在平台的应用密钥设置到服务器之前，{names} 的连接按钮无法使用。",
  "The Connect button for TikTok.": "TikTok 的连接按钮。",
  "The Connect button for Twitch.": "Twitch 的连接按钮。",
  "The Connect button for YouTube.": "YouTube 的连接按钮。",
  "The Connect buttons for Facebook and Instagram.": "Facebook 和 Instagram 的连接按钮。",
  "The copy": "副本",
