  "The cost on file is out of date": "登记成本已过时",
  "The count matches exactly.": "清点金额完全吻合。",
  "The currency reports add up in. Documents in other currencies are shown separately, never converted.": "报表汇总所用的货币。其他货币的单据单独显示，从不换算。",
  "the customer": "该客户",
  "The customer collects it at the counter: charge it on the till then.": "顾客到柜台取餐：那时在收银机收款。",
  "The customer has paid the invoice in full, so the share can be paid.": "客户已全额付清发票，因此可以支付提成。",
  "The customer is {name}.": "客户是 {name}。",
  "The customer is told by text and email. A fault in the making goes to quality too.": "将通过短信和邮件通知客户。制造缺陷也会通报质量部门。",
  "The customer pays": "顾客支付",
  "The customer pays on their phone": "顾客用手机付款",
  "The customer pays the menu price; the receipt shows the taxes in it.": "顾客按菜单价付款；收据会列出其中所含税费。",
