  "The kitchen screen only.": "仅限厨房屏幕。",
  "The kitchen sees it in red on every ticket of this order, and each dish that has it. The till warns you before you add one.": "厨房会在此订单的每张单上以红色看到它，以及含有它的每道菜。添加这类菜前收银机会提醒您。",
  "The kitchen sees it under the dish, and it prints on the receipt.": "厨房会在菜品下方看到它，也会打印在收据上。",
  "The kitchen starts": "厨房开始时间",
  "The kitchen starts at once; the cashier takes the money when the customer comes with their number.": "厨房立即开始制作；顾客凭号码来时由收银员收款。",
  "The kitchen starts on it by itself, its prep time ahead.": "厨房会按准备时间提前自动开始制作。",
  "The kitchen starts on it in good time. You can still cancel until then.": "厨房会按时开始制作。在此之前您仍可取消。",
  "The kitchen's food for this order has been served.": "这一单的菜品已上齐。",
