  "The last 6 months, in {currency}. When the green bar keeps up with the blue, customers are paying on time.": "最近 6 个月，以 {currency} 计。绿色柱跟得上蓝色柱，说明客户按时付款。",
  "The last 60 days": "最近 60 天",
