  "the last 90 days": "近 90 天",
  "The last 90 days of requests you could decide, newest first: who decided, how, and how long it took.": "过去 90 天内您有权决定的申请，最新的在前：谁决定的、结果如何、用了多久。",
  "The last 90 days, by payment method. Press one to show only those.": "过去 90 天，按付款方式。点击一个只显示这些。",
