  "The last Square import was stopped by a server restart. Run it again to finish — nothing is imported twice.": "上次 Square 导入因服务器重启而中断。再次运行即可完成——不会重复导入。",
  "the last survey": "最近一次调查",
  "The last twelve months": "过去十二个月",
  "The last twelve months, in {currency}: what was invoiced and what tenants paid.": "过去十二个月（{currency}）：开票金额与租户付款。",
  "The last two weeks": "最近两周",
  "The latest": "最近记录",
  "The latest {n}, one by one": "最新的 {n} 个，逐一查看",
  "the latest {when}": "最新一条 {when}",
  "The latest 30, here and through the Claude app, with how each one ended.": "最近 30 项（此处及通过 Claude 应用），以及每项的结果。",
  "The latest money received.": "最近收到的款项。",
  "The leads that came in {period}: how many became prospects, were won, and have paid.": "{period}新进的线索：多少成为潜在客户、赢单并已付款。",
  "The leases and contracts the companies are bound by: what they cost, the last day to give notice, and the ones that renew themselves. Reminders come before the notice date and before the end.": "公司须遵守的租约与合同：费用、最后通知日期，以及哪些会自动续约。在通知日期和到期之前都会发出提醒。",
  "The letter": "信函",
  "The log": "日志",
  "The logo, colours, fonts and voice, and every file you need to make something look like us. Open to everyone.": "标志、颜色、字体和语气，以及让作品具有我们风格所需的所有文件。对所有人开放。",
  "the longest {n} late": "最长逾期 {n}",
  "The longest late first, with who has it and the next step.": "逾期最久的排在前面，并列出负责人和下一步。",
  "The longest overdue first, with a number to call.": "逾期最久的在前，并附联系电话。",
