  "This invoice is paid; it cannot be voided.": "这张发票已付清，不能作废。",
  "this is {n}% of it": "占其 {n}%",
  "This is a refund; its date is its credit note's.": "这是退款，其日期跟随贷项通知单。",
  "This is the only time these are shown. Give them to their developer privately (not in a group chat); they go in their system's settings. If one is lost, make a new one from the feed's menu.": "这是唯一一次显示。请私下交给对方开发人员（不要发到群聊）；它们应填在对方系统的设置中。如果丢失，可在数据源菜单中重新生成。",
  "This is who you can see. You cannot change it yourself: HR or another administrator can.": "这是您可以看到的人员范围。您不能自行更改：人事部或其他管理员可以更改。",
  "This is your own claim, so someone else who approves claims must decide it.": "这是您自己的申请，须由其他审批人审批。",
  "This kind of file cannot be shown here. Download it to open it on your device.": "此类文件无法在这里显示。请下载后在您的设备上打开。",
  "This kind of file cannot be shown in the browser. Download it to open it on your device.": "浏览器无法显示此类文件。请下载后在您的设备上打开。",
