  "This only records the decision. A deduction from pay or from next year's leave is made where it belongs (payroll, or that person's total).": "这里只记录决定。从工资或明年假期中扣除，需在相应位置操作（工资单，或该员工的总额）。",
  "this option": "此选项",
  "This order": "本次订单",
  "This order has no pin. Tap the map where it goes, so the rider and the map can find it (optional).": "这个订单没有定位。在地图上点一下送达的地方，方便骑手和地图找到（可选）。",
  "This order was cancelled": "这个订单已取消",
  "This page updates by itself.": "此页面会自动更新。",
  "This payment came from Square, and the next Square import would put its date back. Change it in Square.": "这笔付款来自 Square，下次 Square 导入会把日期改回去。请在 Square 中修改。",
  "This period": "本周期",
  "This permanently removes all {terminatedCount} terminated employee record(s) and their logins. Unlike deleting a single employee, this cannot be undone — their attendance, leave and work order history will remain but will no longer show a name.": "这将永久删除全部 {terminatedCount} 条已离职员工记录及其登录。与删除单个员工不同，此操作无法撤销——他们的考勤、休假和工单记录会保留，但不再显示姓名。",
  "This person is on the list more than once; leave one line out.": "此人在名单上出现了不止一次；请去掉其中一行。",
  "This person is on the sheet more than once; leave one row out.": "此人在表中出现了不止一次；请去掉其中一行。",
  "This phone cannot share where it is.": "这部手机无法分享位置。",
  "This phone cannot tell where it is: tap the map instead.": "这部手机无法确定位置：请直接点地图。",
  "This phone cannot tell where it is.": "此手机无法获取所在位置。",
  "This photo shows": "这张照片展示",
  "This picture comes from Square; Import from Square updates it if it changes there. Upload your own to keep it instead.": "这张图片来自 Square；如果 Square 上的图片有变化，从 Square 导入时会更新它。上传您自己的照片即可改为保留您的照片。",
  "This printer has no Bluetooth Low Energy printing the browser can use: it probably only speaks classic Bluetooth, which web pages cannot reach. Connect it with its USB cable instead, or use a printer that supports Bluetooth LE.": "这台打印机没有浏览器可用的低功耗蓝牙打印功能：它很可能只支持经典蓝牙，网页无法连接。请改用 USB 线连接，或使用支持低功耗蓝牙（BLE）的打印机。",
