  "What do you need?": "您需要什么？",
  "What each asset cost, what it has lost and what it is still worth on any day; the year by month; what one fetched when it went, against its book value.": "每项资产的成本、已折旧金额及任意日期的剩余价值；全年按月；处置时收回的金额与账面价值的对比。",
  "What each company means to spend each month, against what it did: bills, payroll, expense sheets and fuel.": "各公司每月计划支出与实际支出对比：账单、工资、费用表和燃油。",
  "What each holds, the moisture it dries to, and how long a charge usually takes.": "每个的容量、干燥到的湿度，以及一批通常需要多久。",
