  "What each part of the day took in {month}. Press a shift for its hours.": "{month} 一天中各时段的收入。点击班次查看各小时。",
  "What each product is made of, what one really costs with labour and overhead, the margin it leaves, and what the stock can make.": "每个产品由什么组成、含人工和间接费用的真实成本、利润空间，以及现有库存能生产多少。",
  "What each role can do": "各角色的权限",
