  "What each till has taken so far today, hour by hour, against the same day last week.": "每个收银台今天到目前为止逐小时的营业额，与上周同一天对比。",
  "What each type of leave is worth, everyone's days for {year}, and each company's public holidays. Press a number to jump to it.": "每类假期的天数、每个人 {year} 年的假期，以及各公司的公共假日。点击数字即可跳转。",
  "What ends in the next twelve months": "未来十二个月内到期的",
