  "What is it": "是什么",
  "What is it about?": "会议主题是什么？",
  "What is it for?": "用途是什么？",
  "What is it for? What must it say? Sizes, where it will be used, anything it must include…": "用途是什么？必须传达什么？尺寸、用在哪里、必须包含的内容……",
  "What is it?": "这是什么？",
  "What is it? (optional)": "这是什么？（可选）",
  "what is left for the owners": "留给所有者的",
  "What is left of each thing counted. A sale takes counted dishes and drinks off by itself; when new stock comes in, or after counting, enter it here.": "每样计数物品的剩余。销售会自动扣减计数的菜品和饮料；新货到时或盘点后，在这里录入。",
  "What is left of the price after the cost price, as a share of the price.": "售价减去成本价后的剩余部分，占售价的比例。",
  "What is left on it ({amount}) is given back in cash from your drawer.": "卡内余额（{amount}）将从您的钱箱以现金退还。",
  "What is left stays on the card for next time.": "余额留在卡上，下次可用。",
  "What is needed": "需要什么",
  "What is needed each time?": "每次需要什么？",
  "What is on the shelf now. It follows the daily stock sheet: each day opens at the day before's closing, adds what was received and takes off what was sold, moved or broken; a count replaces the expected figure.": "现在货架上的数量。它与每日库存表同步：每天以前一天的结存为期初，加上收货，减去销售、调拨或破损；清点数会取代预计数。",
  "What is scored, 1 to 5": "评分项目（1 到 5）",
  "What is short?": "缺什么？",
  "What is still owed, by how far past the due date. Press one to show only those.": "按逾期天数列出的仍欠款项。点击一个只显示这些。",
  "What is still to pay on invoices that are not paid or voided, added up in each currency.": "未付清且未作废的发票上仍需支付的金额，按币种合计。",
  "What is still to pay on unpaid and part-paid invoices today, whatever the period.": "无论期间如何，今天未付和部分付款发票上仍待支付的金额。",
  "What is the occasion?": "是什么场合？",
  "What is this group for? (optional)": "这个群组是做什么的？（可选）",
  "What is waiting for your decision.": "等待您决定的事项。",
  "What is wrong": "问题",
  "What is wrong?": "出了什么问题？",
  "What is wrong? e.g. a leg is loose and it wobbles": "哪里有问题？例如：一条腿松了，会晃",
  "What is wrong? e.g. not cooling, 12° inside": "出了什么问题？例如：不制冷，里面 12°",
  "What it bought (optional), e.g. 2 crates of tomatoes": "买了什么（可选），例如：2 箱西红柿",
