  "What lets an employee sign in: a login email, a password and one or more roles. Employees without one can still be clocked in at the kiosk and paid.": "让员工能够登录的东西：登录邮箱、密码以及一个或多个角色。没有账户的员工仍可在打卡机打卡并领取薪资。",
