  "What marketing has planned, in one month: campaigns, posts, events, promotions and their codes, your requests to marketing, public holidays and the year's big moments to sell around.": "市场部的计划，一个月一览：活动、帖子、展会、促销及其优惠码、你提交给市场部的请求、公共假日，以及全年可借势销售的重要时刻。",
  "What Meta says about the WhatsApp account": "Meta 对该 WhatsApp 账号的通知",
