  "What one is made of": "组成",
  "What reaches you after SSNIT and PAYE are taken off the gross. Where the company pays your PAYE, only SSNIT is taken off.": "从总额中扣除 SSNIT 和 PAYE 后您实际拿到的金额。如果公司承担您的 PAYE，则只扣除 SSNIT。",
  "What sells": "畅销产品",
  "What sells most, and what customers rate best.": "卖得最多、评分最高的商品。",
  "What sold most in the last {n} days: worth featuring in posts and offers.": "最近 {n} 天卖得最多的：值得在帖子和优惠中重点推荐。",
  "What someone uses to clock in and out at the attendance kiosk.": "在考勤机上打卡时使用的方式。",
  "What spoilt them?": "报废原因？",
  "What spoilt them? e.g. split in the press": "报废原因？例如：压制时开裂",
  "What staff can ask for from My space.": "员工可在“我的空间”申请的额度。",
  "What staff receive: gross pay less their SSNIT, and less PAYE unless their company pays it for them.": "员工实际拿到的：总额减去其 SSNIT，除非公司为其承担 PAYE，否则还要减去 PAYE。",
  "What stands out": "重点关注",
  "What stopped it:": "停止原因：",
