  "what the company has": "公司拥有的",
  "What the company has asked marketing for, and where each is.": "公司向市场部提出的请求及其进展。",
  "What the company has asked marketing for. Take each on, assign it, keep the one who asked posted and attach the finished work here.": "公司向市场部提出的请求。接手每一项、分配负责人、及时告知提出者，并在此附上完成的作品。",
  "What the company means to get done this quarter, each team's part in it, and where every key result stands — checked in each week by its owner.": "公司本季度要完成的事、各团队的部分，以及每个关键结果的进展——由负责人每周更新。",
  "What the company means to spend, by category. Empty: no budget for it.": "公司计划按类别支出的金额。留空：不设预算。",
  "What the company pays in all: gross pay plus the employer's SSNIT, plus PAYE where the company pays it.": "公司支付的总额：工资总额加雇主 SSNIT，公司承担 PAYE 时再加上 PAYE。",
  "What the customer said": "客户的回复",
  "What the deductions cover": "扣减项包含的内容",
  "What the guest said (feedback)": "客人的反馈",
  "What the items sold for before discounts. The ranking of dishes and the kitchen bonus use it.": "菜品折扣前的售价。菜品排名和厨房奖金均以此计算。",
  "What the labels mean": "标签含义",
  "What the project is for and what \"done\" looks like.": "项目的目的以及“完成”是什么样子。",
  "What the requester expected it to cost, for all of the quantity.": "申请人预计的总花费（全部数量）。",
  "What the texts are for": "短信用途",
  "What the till sells, at what price, and what is left.": "收银台卖什么、什么价格、还剩多少。",
  "What the till sells, with what each item sold in the last 30 days.": "收银台销售的菜品，以及每项过去 30 天的销量。",
  "What the till sends to the kitchen shows on a screen there: open the kitchen screen on a tablet or TV in the kitchen and sign in with a staff PIN.": "收银台发往厨房的内容会显示在厨房的屏幕上：在厨房的平板或电视上打开厨房屏幕，并用员工 PIN 码登录。",
  "What the till took, how guests paid, what was spent, and whether the cash drawers balanced.": "收银台收了多少、宾客如何付款、支出了多少，以及钱箱是否平账。",
  "What the website sells": "网站在卖什么",
  "What the workshop is making: the parts taken from stock by the bill of materials, the good ones into stock and what was spoilt, and what each job really cost against its bill.": "车间在生产什么：按物料清单从库存领用零件，合格品入库并记录报废，以及每个任务与清单相比的实际成本。",
