  "What was found": "发现",
  "What was invoiced each month, and the payments that came in that month, in GHS. Hover a month for the figures.": "每月开票金额和当月收到的付款（GHS）。将鼠标移到某个月查看数字。",
  "What was it?": "是什么？",
