  "What was taken goes back into stock.": "已领用的物料将退回库存。",
  "What was there at the start of the day: the previous day's closing, or the product's stock before its first day on the sheet.": "当天开始时的数量：前一天的结存，或产品首次上表前的库存。",
  "What we hand out": "发放物品目录",
  "What we owe suppliers, across Bamboo Products and the restaurants: approved, paid, with the slip.": "我们欠供应商的款项，涵盖 Bamboo Products 和各餐厅：审批、付款并附凭证。",
