  "What went well": "做得好的地方",
  "What went wrong?": "哪里不满意？",
  "What worked, what did not, what to do next time": "哪些有效、哪些无效、下次该怎么做",
  "What would you like changed?": "您想修改什么？",
  "What would you like us to make?": "您想让我们制作什么？",
  "What would you like?": "您想预约什么？",
  "What you are entitled to, what you have taken and what is left.": "你的应得天数、已休天数和剩余天数。",
  "What you bought, what it cost and a photo of the receipt.": "买了什么、花了多少钱，以及收据照片。",
