  "What you want, how many and by when: sent to each supplier you pick, their prices side by side when they reply.": "要什么、要多少、何时要：发给您选的每家供应商，回复后价格并列比较。",
  "What, how many and why: it comes off the stock, and the manager sees what it cost.": "什么、多少、为什么：会从库存中扣除，经理能看到损失了多少钱。",
  "WhatsApp": "WhatsApp",
  "WhatsApp {name}": "WhatsApp 联系 {name}",
  "WhatsApp {number} is connected.": "WhatsApp {number} 已连接。",
  "WhatsApp disconnected from the inbox.": "WhatsApp 已从收件箱断开。",
  "WhatsApp disconnected from the OS.": "WhatsApp 已与系统断开。",
  "WhatsApp isn't set up for the OS yet. An administrator finishes Integrations → WhatsApp first; then each restaurant connects its number here.": "系统尚未设置 WhatsApp。请管理员先完成“集成 → WhatsApp”，然后各餐厅在这里连接自己的号码。",
  "WhatsApp it": "通过 WhatsApp 发送",
  "WhatsApp opened for {name} — press send there.": "已为 {name} 打开 WhatsApp——请在那里点发送。",
  "WhatsApp opened with the message ready — press send there.": "已打开 WhatsApp，消息已写好——请在那里点发送。",
  "WhatsApp opened with the statement's link.": "已打开 WhatsApp，并附上对账单链接。",
  "WhatsApp or phone": "WhatsApp 或电话",
  "WhatsApp Status": "WhatsApp 状态",
  "WhatsApp to {phone}": "已通过 WhatsApp 发送至 {phone}",
  "WhatsApp, calls and follow-ups": "WhatsApp、电话与跟进",
  "WhatsApp, email, Facebook, Instagram": "WhatsApp、邮件、Facebook、Instagram",
  "WhatsApp:": "WhatsApp：",
  "When": "时间",
  "When a licence, permit, certificate or insurance runs out. Whoever looks after documents is warned 60, 30, 14 and 7 days before.": "执照、许可证、证书或保险到期的日期。负责文件的人会在到期前 60、30、14 和 7 天收到提醒。",
  "When a material gets down to this, it is running low and it is time to buy more.": "材料降到这个数量时即库存不足，应该补购。",
  "When a table orders or calls from its QR code, it shows here and the till rings.": "餐桌扫码点餐或呼叫时，会显示在这里并且收银机会响铃。",
  "When an item gets down to this, it is time to buy more.": "物品降到这个数量时就该补购了。",
  "When and how much": "时间与预算",
  "When and where": "时间和地点",
  "When customers write": "客户什么时候联系",
  "When it is busy": "繁忙时段",
  "When on (Company settings → Email), the OS emails the same reminders itself before and after the due date, at most once per step.": "开启后（公司设置 → 电子邮件），系统会在到期前后自动发送同样的提醒邮件，每个阶段最多一次。",
  "When people are expected, and when they count as late.": "人员应到时间，以及何时算迟到。",
  "When people arrived this morning, and the last seven days.": "今天上午大家的到岗时间，以及最近七天。",
  "When the asset is next due for a service. Logging a service moves it on by the asset's service interval, if it has one.": "资产下次需要保养的时间。记录一次保养后，会按资产的保养间隔自动顺延（如有）。",
  "When the kitchen marks a delivery ready, it comes here to send with a rider.": "厨房把外送标为做好后，会出现在这里，等着交给骑手。",
  "When the money came in. Today counts it as money in this week.": "款项到账的日期。选今天会计入本周收款。",
  "When the notice date comes, we mean to:": "到通知日期时，我们打算：",
  "When the stock falls to this, the product shows as low and the morning summary mentions it. 0 means no warning.": "库存降至此数时，产品会显示为偏低，早间摘要也会提及。0 表示不提醒。",
  "When the ticket reached the kitchen": "单到达厨房的时间",
  "When they buy, raise the quotation and invoice for {name}, then link the invoice here.": "对方购买时，为 {name} 开具报价单和发票，然后在此关联发票。",
  "When they last bought": "最近一次购买",
  "When they tap their PIN or face at the clock-in kiosk, the kiosk answers in this language. Pick 中文 for staff who read Chinese.": "当他们在打卡机上输入 PIN 或刷脸时，打卡机会用这种语言显示结果。阅读中文的员工请选择 中文。",
  "When this is on an invoice, the quantity comes off this product in Products & inventory — one of this takes one of that, so link items counted the same way (a bundle of 10 linked to single slats takes 1 slat, not 10).": "当它出现在发票上时，数量会从「产品与库存」中的此产品扣除——此项的 1 个扣除该产品的 1 个，因此请关联计数方式相同的项目（10 根一捆关联到单根板条时，只会扣除 1 根，而不是 10 根）。",
  "When turned on in Company settings, the OS texts people itself before and after the due date, at most once per step.": "在公司设置中开启后，系统会在到期日前后自动发送短信，每个阶段最多一次。",
  "When you ask it to do something, it checks the request and shows a card. Nothing happens until you press Confirm on it.": "当您让它做某事时，它会检查请求并显示一张卡片。在您按确认之前不会发生任何事。",
  "When you go home, tap your PIN here again.": "下班回家时，请在这里再次输入您的 PIN。",
  "When, and for what rent?": "何时搬，租金多少？",
  "When?": "什么时候？",
  "Where": "住址",
  "Where (area or town)": "地点（地区或城镇）",
  "Where (optional)": "在哪里（可选）",
  "Where {company} is online. Connect a channel to sync its numbers, or log them by hand.": "{company} 的线上渠道。连接渠道以同步数据，或手动记录。",
