  "With the read key (it starts with bfk_). days gives every day you ask for, for every staff member: status present, late, absent (no clock-in on a working day), leave (approved leave), off (their day off) or half_day, with the clock-in and clock-out. Any range: a long one comes a month at a time, so ask again with next until it is null. Days before someone was hired and days still to come are left out. changes gives what changed since you last asked (start with after=0, then send back next); staff lists everyone in the feed.": "使用读取密钥（以 bfk_ 开头）。days 返回所请求的每一天、每位员工的状态：present、late、absent（工作日没有打卡）、leave（已批准的休假）、off（休息日）或 half_day，并附上上班和下班时间。任意日期范围：较长的范围按每次一个月返回，请用 next 继续请求，直到它为 null。入职前的日期和尚未到来的日期不包含在内。changes 返回自上次请求以来的变更（先用 after=0，之后传回 next）；staff 列出数据源中的所有员工。",
